# AI Office v2.5 Part I External Intelligence Provider Architecture Installer
$ErrorActionPreference = "Stop"
$Repository = "E:\AI\AI-Office"
if (-not (Test-Path -LiteralPath $Repository -PathType Container)) { throw "AI Office repository not found." }
Set-Location $Repository
$Timestamp = Get-Date -Format "yyyyMMdd-HHmmss"
$BackupDirectory = Join-Path $Repository ("workspace\installer-backups\v2.5-part-i-" + $Timestamp)
New-Item -ItemType Directory -Path $BackupDirectory -Force | Out-Null
foreach ($Directory in @("config\intelligence","scripts\intelligence","workspace\templates","docs")) { New-Item -ItemType Directory -Path (Join-Path $Repository $Directory) -Force | Out-Null }
function Write-EmbeddedFile {
    param([string]$RelativePath,[string]$Base64Content)
    $Destination = Join-Path $Repository $RelativePath
    $Parent = Split-Path -Parent $Destination
    if ($Parent -and -not (Test-Path -LiteralPath $Parent)) { New-Item -ItemType Directory -Path $Parent -Force | Out-Null }
    if (Test-Path -LiteralPath $Destination -PathType Leaf) {
        $BackupPath = Join-Path $BackupDirectory $RelativePath
        $BackupParent = Split-Path -Parent $BackupPath
        if ($BackupParent -and -not (Test-Path -LiteralPath $BackupParent)) { New-Item -ItemType Directory -Path $BackupParent -Force | Out-Null }
        Copy-Item -LiteralPath $Destination -Destination $BackupPath -Force
    }
    [IO.File]::WriteAllBytes($Destination,[Convert]::FromBase64String($Base64Content))
    Write-Host "[WRITTEN] $RelativePath" -ForegroundColor Green
}
Write-EmbeddedFile -RelativePath "config\intelligence\external-provider-policy.json" -Base64Content ""
Write-EmbeddedFile -RelativePath "config\intelligence\external-provider-schema.json" -Base64Content ""
Write-EmbeddedFile -RelativePath "workspace\templates\external-provider-template.json" -Base64Content "ewogICJwcm92aWRlciI6ICIiLAogICJzdXBwb3J0ZWQiOiBmYWxzZSwKICAiZW5hYmxlZCI6IGZhbHNlLAogICJjcmVkZW50aWFsX2NvbmZpZ3VyZWQiOiBmYWxzZSwKICAibW9kZWxfY29uZmlndXJlZCI6IGZhbHNlLAogICJhY3RpdmF0aW9uX3JlYWR5IjogZmFsc2UsCiAgImNoZWNrZWRfYXQiOiAiIgp9Cg=="
Write-EmbeddedFile -RelativePath "scripts\intelligence\Get-AIOfficeExternalProviderStatus.ps1" -Base64Content ""
Write-EmbeddedFile -RelativePath "scripts\intelligence\Show-AIOfficeExternalProviderStatus.ps1" -Base64Content ""
Write-EmbeddedFile -RelativePath "scripts\intelligence\Resolve-AIOfficeExternalProvider.ps1" -Base64Content ""
Write-EmbeddedFile -RelativePath "scripts\intelligence\Test-AIOfficeExternalProviderArchitecture.ps1" -Base64Content ""
Write-EmbeddedFile -RelativePath "docs\AI-Office-v2.5-Part-I-External-Intelligence-Provider-Architecture.md" -Base64Content ""
$Scripts = @(
"E:\AI\AI-Office\scripts\intelligence\Get-AIOfficeExternalProviderStatus.ps1",
"E:\AI\AI-Office\scripts\intelligence\Show-AIOfficeExternalProviderStatus.ps1",
"E:\AI\AI-Office\scripts\intelligence\Resolve-AIOfficeExternalProvider.ps1",
"E:\AI\AI-Office\scripts\intelligence\Test-AIOfficeExternalProviderArchitecture.ps1")
foreach ($Script in $Scripts) {
  $Tokens=$null; $ParseErrors=$null
  [System.Management.Automation.Language.Parser]::ParseFile($Script,[ref]$Tokens,[ref]$ParseErrors)|Out-Null
  if ($ParseErrors.Count -gt 0) { throw ("Syntax error in " + $Script + ": " + (($ParseErrors|ForEach-Object{$_.Message}) -join "; ")) }
}
Write-Host ""
Write-Host "AI Office v2.5 Part I External Intelligence Provider Architecture installed successfully." -ForegroundColor Green
Write-Host "No external provider or paid inference has been activated." -ForegroundColor Cyan
Write-Host "Local-first production behavior remains unchanged." -ForegroundColor Cyan
Write-Host "Backups: $BackupDirectory" -ForegroundColor Cyan